package com.apple.spark.security;

import com.apple.spark.core.Constants;
import io.dropwizard.auth.AuthFilter;
import io.dropwizard.auth.basic.BasicCredentials;
import java.security.Principal;
import javax.annotation.Nullable;
import javax.ws.rs.WebApplicationException;
import javax.ws.rs.container.ContainerRequestContext;

/**
 * This auth filter accepts a header that contains the user, and uses that for basic authentication.
 * This provides more flexibility of how to pass in the user name.
 */
public class UserNameAuthFilter<P extends Principal> extends AuthFilter<BasicCredentials, P> {

    private UserNameAuthFilter() {
    }

    @Override
    public void filter(ContainerRequestContext requestContext) {
        BasicCredentials credentials = this.getCredentials(requestContext.getHeaders().getFirst(Constants.USER_HEADER_KEY));
        if (!this.authenticate(requestContext, credentials, "BASIC")) {
            throw new WebApplicationException(this.unauthorizedHandler.buildResponse(this.prefix, this.realm));
        }
    }

    @Nullable
    private BasicCredentials getCredentials(String header) {
        if (header == null) {
            return null;
        } else {
            String username = header;
            String password = "";
            return new BasicCredentials(username, password);
        }
    }

    public static class Builder<P extends Principal> extends AuthFilterBuilder<BasicCredentials, P, UserNameAuthFilter<P>> {

        public Builder() {
        }

        protected UserNameAuthFilter<P> newInstance() {
            return new UserNameAuthFilter();
        }
    }
}

